%% c2a_second_level_regression.m
%
%
% *USAGE*
%
% This script displays second-level (i.e. across subjects) regression
% results generated by prep_3a_run_second_level_regression_and_save.m
%
% Run this script with Matlab's publish function to generate html report of results:
% publish('c2a_second_level_regression','outputDir',htmlsavedir)
% 
% See the documentation of prep_3a_run_second_level_regression_and_save.m
% for more info and options
%
%
% *OPTIONS FOR CURRENT SCRIPT*
% 
%   NOTE: 
%       defaults are specified in a2_set_default_options for any given model,
%       but if you want to run the same model with different options, 
%       you can make a copy of this script with a letter index (e.g. _s6a_) 
%       and change the default option below
%
% _GLM options_
%
% * save_figures_glm                true saves .svg files of all figures generated by c2a_second_level_regression.m (slow, takes up space)
%
% * q_threshold_glm                 threshold for FDR-corrected display items
%
% * p_threshold_glm                 threshold for uncorrected display items
%
% * k_threshold_glm                 extent threshold for both corrected and uncorrected display items
%
% * BF_threshold_glm                threshold for Bayes Factor maps, |BF| > 10 indicates strong evidence in favour of H1 (positive value) or H0 (negative value) - see help.statistic_image.estimateBayesFactor for details
%
%
% _MVPA options_
%
% * dobootstrap_mvpa_reg_cov
%
%     mvpa bootstrapping options
%
%       * boot_n_mvpa_reg_cov           number of bootstrap samples
%
%       * parallelstr_mvpa_reg_cov      'parallel'/'noparallel'  
%
%       * cons2boot_mvpa_reg_cov        vector of indices of conditions/contrasts to bootstrap
%
%     mvpa thresholding options
%
%       * q_threshold_mvpa_reg_cov      threshold for fdr-corrected maps
%
%       * k_threshold_mvpa_reg_cov      extent threshold (in voxels)
%
%
% *OPTIONS TO COPY FROM CORRESPONDING PREP_3a_ SCRIPT*
%
% _Mandatory options_
%
% * mygroupfieldname                    'contrasts'/'conditions'
%
% * results_suffix                      name added to results file by prep_3a script in case of multiple versions of model, e.g. 'covariate_rating'
%
%
% _Options to copy if specified in prep_3a script_
%
% * covs2use                            cell array of covariate used
%
% * group_id                            group variable name
%
%
% _Custom options from prep_3a script_
% 
% see first section of this script below for overview
%
% -------------------------------------------------------------------------
%
% revamped by: Lukas Van Oudenhove
%
% date:   Dartmouth, May, 2022
%
% -------------------------------------------------------------------------
%
% c2a_second_level_regression.m         v8.4
%
% last modified: 2026/08/14
%
%
%% GET AND SET OPTIONS
% -------------------------------------------------------------------------

% GET MODEL-SPECIFIC PATHS AND OPTIONS

a_set_up_paths_always_run_first;

% NOTES 
%   1. CHANGE THIS TO THE MODEL-SPECIFIC VERSION OF THIS SCRIPT
%   2. THIS WILL ALSO AUTOMATICALLY CALL A2_SET_DEFAULT_OPTIONS


% COPY OPTIONS FROM CORRESPONDING PREP_3a_ SCRIPT

% Mandatory options from prep_3a script

mygroupnamefield = 'contrasts'; 
results_suffix = ''; % suffix of your choice added to .mat file with saved results

% Options to copy if specified in prep_3a script

% covs2use = {'varname1'};
% group_id = {'varname2'};

% Custom options from prep_3a script

% dorobust = true/false;
% dorobfit_parcelwise = true/false;
%   csf_wm_covs = true/false;
%   remove_outliers = true/false;
% atlasname_glm = 'atlas_name';
% atlas_granularity = 1/2/3;
% maskname_glm = 'mask_name';
% myscaling_glm = 'raw'/'scaled'/'scaled_contrasts';
% design_matrix_type = 'custom'/'group'/'onesample';
% doBayes = true/false;
% doTFCE = true/false;
%     perm_n_tfce = 1000;                                                    
%     tfce_sidedness = 'two';                                                
%     tfce_tail = 'pos/neg';  
%     tfce_correction = 'fwe'/'fdr';                                         
%         which multiple-comparisons correction to report for TFCE. 'fwe'
%         (default) uses the max-statistic FWE p-values (Smith & Nichols
%         2009) returned in tfce_info.p_FWE by group_tfce_from_subject_maps;
%         'fdr' uses FDR on the uncorrected permutation p-values, the old
%         behaviour. Both thresholded maps are saved either way - only the
%         reported one gets montages and region tables, since labelling
%         regions against an atlas is by far the slowest step here.
%         TFCE results generated before p_FWE was implemented carry no
%         p_FWE field and fall back to 'fdr' with a warning.
%     p_threshold_fwe = .05;                                                 
%         threshold for the FWE-corrected TFCE p-values. These are already
%         corrected, so they are thresholded uncorrected at this value -
%         applying FDR on top would correct twice.
% domvpa_reg_cov = true/false;
%   algorithm_mvpa_reg_cov = 'cv_pcr'/'cv_pls'/etc;
%   holdout_set_method_mvpa_reg_cov = 'no_group'/'group';
%   nfolds_mvpa_reg_cov = x;
%   zscore_outcome_mvpa_reg_cov = true/false;

% SET CUSTOM OPTIONS FOR CURRENT SCRIPT

% NOTE 
%   only specify if you want to run a second version of your model with different options
%   than the defaults you set in your model-specific version of a2_set_default_options.m
%   EXCEPTION: cons2boot_mvpa_reg_cov, which is not in the a2 script, but can be used here
%       if you do not want to bootstrap all contrasts

% GLM options

% save_figures_glm = true/false;
% q_threshold_glm = .x;
% p_threshold_glm = .yyy;
% k_threshold_glm = zz;
% BF_threshold_glm = x;

% MVPA options

% dobootstrap_mvpa_reg_cov = true/false;
    % mvpa bootstrapping options
%     boot_n_mvpa_reg_cov = x;                                      
%     parallelstr_mvpa_reg_cov = 'parallel'/'noparallel'; 
%     cons2boot_mvpa_reg_cov = [y1,y2,...];
    % mvpa thresholding options
%     q_threshold_mvpa_reg_cov = .yy;                                  
%     k_threshold_mvpa_reg_cov = z; 

% GET SCALING OPTION

switch myscaling_glm

    case 'raw'
        fprintf('\ncontrast calculated on raw (unscaled) condition images used in second-level GLM\n\n');
        scaling_string = 'no_scaling';

    case 'scaled'
        fprintf('\ncontrast calculated on z-scored condition images used in second-level GLM\n\n');
        scaling_string = 'scaling_z_score_conditions';

    case 'scaled_contrasts'
        fprintf('\nl2norm scaled contrast images used in second-level GLM\n\n');
        scaling_string = 'scaling_l2norm_contrasts';

    otherwise
        error('\ninvalid option "%s" defined in myscaling_glm variable in a2_set_default_options script, choose between "raw", "scaled", or "scaled_contrast" given option "%s" defined in mygroupnamefield variable\n', myscaling_glm, mygroupnamefield);

end


% GET MASKING OPTION

% NOTE: In case of parcelwise regression, masking is already done in prep_3a script as part of robfit_parcelwise, but we need the atlas object and define mask_string var

if ~dorobfit_parcelwise

    if exist('maskname_glm', 'var') && ~isempty(maskname_glm) && exist(maskname_glm, 'file')
        
        apply_mask_before_fdr = true;
        
        [~,maskname_short] = fileparts(maskname_glm);
            if contains(maskname_short,'nii')
                [~,maskname_short] = fileparts(maskname_short);
            end
            
        mask_string = sprintf('masked with %s', maskname_short);
        
        glmmask = fmri_mask_image(maskname_glm, 'noverbose'); 
            if any(unique(glmmask.dat) ~= 1)
                glmmask.dat(glmmask.dat > 0) = 1; % binarize mask if needed
            end
            
        fprintf('\nMasking voxelwise results visualization with %s\n\n', maskname_short);
        
        % MONTAGE OF MASK
        
        % canlab_results_fmridisplay's 'compact' layout only calls axes('Position',...);
        % unlike 'multirow' it never opens a figure of its own, so it draws into whatever
        % figure is current - the previous block's montage, or the last figure left open by
        % the previous script in the same session. Open a fresh one. ('multirow' does
        % create its own figure, so those call sites are deliberately left alone: adding
        % figure; there would leave an empty figure behind for every montage.)
        figure;
        o2 = canlab_results_fmridisplay([], 'compact');
        o2 = addblobs(o2, glmmask,'onecolor','color',[0.4 0.2 0.6],'trans','transvalue',0.50);
        o2 = title_montage(o2, 5, ['voxel-wise analysis masked with: ' maskname_short]);
        plugin_set_figure_size;
        drawnow,snapnow;
        
        clear o2
        
    else
        
        apply_mask_before_fdr = false;
        mask_string = sprintf('without masking');
        fprintf('\nShowing voxelwise results without masking\n\n');
        
    end 

end

if exist('atlasname_glm','var') && ~isempty(atlasname_glm)

    if contains(atlasname_glm,'.mat')
        
        load(atlasname_glm);
        [~,atlasname_short] = fileparts(atlasname_glm);
        clear mask
        
        if logical(exist('atlas_granularity','var')) && atlas_granularity ~= 1
            combined_atlas = combined_atlas.downsample_parcellation(['labels_' num2str(atlas_granularity)]);
        end
        
        if dorobfit_parcelwise
            
            maskname_short = atlasname_short;
            mask_string = sprintf('masked with %s', maskname_short);
            fprintf('\nRunning parcelwise analysis in custom-made atlas %s at granularity level labels_%d\n\n', atlasname_short, atlas_granularity);
            
        end
        
        fprintf('\nLabeling regions using custom-made atlas %s at granularity level labels_%d\n\n', atlasname_short, atlas_granularity);
        
        % MONTAGE OF ATLAS
        
        cmap = colormap('colorcube');
        close gcf;
        
        figure;
        o2 = canlab_results_fmridisplay([], 'compact');
        o2 = addblobs(o2, atlas2region(combined_atlas),'indexmap',cmap,'interp','nearest');
        if dorobfit_parcelwise
            o2 = title_montage(o2, 5, ['parcel-wise analysis in atlas: ' atlasname_short ' at granularity level labels_' num2str(atlas_granularity)]);
        else
            o2 = title_montage(o2, 5, ['voxel-wise analysis labeled with atlas: ' atlasname_short ' at granularity level labels_' num2str(atlas_granularity)]);
        end
        plugin_set_figure_size;
        drawnow,snapnow;
        
        clear o2

    elseif ischar(atlasname_glm)

        combined_atlas = load_atlas(atlasname_glm);
        
        if logical(exist('atlas_granularity','var')) && atlas_granularity ~= 1
            combined_atlas = combined_atlas.downsample_parcellation(['labels_' num2str(atlas_granularity)]);
        end
        
        if contains(atlasname_glm,'canlab2023') || contains(atlasname_glm,'canlab2024')
            combined_atlas = combined_atlas.threshold(0.20); % only keep probability values > 0.20 in probabistic canlab2023 atlas
        end
        
        if dorobfit_parcelwise
            mask_string = sprintf('in atlas %s',atlasname_glm);
            
            fprintf('\nRunning parcelwise analysis in custom-made atlas %s at granularity level labels_%d\n\n', atlasname_glm, atlas_granularity);
            
        end
        
        fprintf('\nLabeling regions using custom-made atlas %s at granularity level labels_%d\n\n', atlasname_glm, atlas_granularity);
        
        % MONTAGE OF ATLAS
        
        cmap = colormap('colorcube');
        close gcf;
        
        figure;
        o2 = canlab_results_fmridisplay([], 'compact');
        o2 = addblobs(o2, atlas2region(combined_atlas),'indexmap',cmap,'interp','nearest');
        if dorobfit_parcelwise
            o2 = title_montage(o2, 5, ['parcel-wise analysis in atlas: ' atlasname_glm ' at granularity level labels_' num2str(atlas_granularity)]);
        else
            o2 = title_montage(o2, 5, ['voxel-wise analysis labeled with atlas: ' atlasname_glm ' at granularity level labels_' num2str(atlas_granularity)]);
        end
        plugin_set_figure_size;
        drawnow,snapnow;
        
        clear o2

    else

         error('\ninvalid option "%s" defined in atlasname_glm variable, should be a keyword for load_atlas.m or a .mat file containing an atlas object, check docs"\n\n',atlasname_glm)

    end

else

    if dorobfit_parcelwise
        mask_string = sprintf('without masking');
        
        fprintf('\nShowing parcelwise results without masking in 489 parcels of canlab_2018 atlas\n\n');
        
    end

end


% LOAD BRAINMASK

brainmask = fmri_mask_image(maskname_brain,'noverbose');


% CHECK Q THRESHOLD IN CASE OF PARCELWISE ANALYSIS

if dorobfit_parcelwise
    
    if q_threshold_glm ~= 0.05
        fprintf('\n');
        warning('Parcelwise analysis only implemented with qFDR < 0.05, will default to this threshold')
        fprintf('\n');
    end
    
end


%% LOAD RESULTS IF NEEDED
% -------------------------------------------------------------------------

%%
% *GLM*

if ~dorobfit_parcelwise
    
    resultsvarname = 'regression_stats_results';
    resultsstring = 'regression_stats_and_maps_';
    analysis_type = 'voxel-wise';
    
else
    
    resultsvarname = 'parcelwise_stats_results';
    resultsstring = 'parcelwise_stats_and_maps_';
    analysis_type = 'parcel-wise';
    
end

if ~exist(resultsvarname, 'var')
    
    fprintf('\n\n');
    printhdr('LOADING GLM DATA');
    fprintf('\n\n');

    savefilenamedata = fullfile(resultsdir, [resultsstring, mygroupnamefield, '_', scaling_string, '_', results_suffix, '.mat']);

    if exist(savefilenamedata,'file')
        fprintf('\nLoading %s regression results and maps from %s\n\n', analysis_type, savefilenamedata);
        load(savefilenamedata);
    else
        fprintf('\nNo saved results file %s. Skipping this analysis.', savefilenamedata);
        fprintf('\nRun prep_3a_run_second_level_regression_and_save.m to get %s regression results first.\n', analysis_type); 
        return
    end

else
    fprintf('\n%s %s found, displaying results\n\n', resultsvarname, analysis_type);

end

if ~dorobfit_parcelwise    
    
    results = regression_stats_results;
    
    if doBayes
        bayesian_results = bayesian_regression_stats_results;
    end
    
    if doTFCE
        tfce_results = tfce_regression_stats_results;
    end

else
    
    results = parcelwise_stats_results;

end

% Bayes factors come from prep_3a's VOXELWISE branch only - the parcelwise
% results file contains just parcelwise_stats_results - so doBayes on its own
% does not tell us whether they are available here. Without this, a parcelwise
% run with doBayes = true dies on an undefined bayesian_results.
has_bayes = doBayes && exist('bayesian_results','var') && ~isempty(bayesian_results);

% Same for TFCE: it is computed in prep_3a's voxelwise branch only, so a
% parcelwise results file has no tfce_regression_stats_results and doTFCE alone
% would send us into an undefined tfce_results.
has_tfce = doTFCE && exist('tfce_results','var') && ~isempty(tfce_results);

% Region tables for the UNCORRECTED TFCE map are off by default: an uncorrected
% TFCE map typically covers tens of thousands of voxels, so the table is long,
% slow to build (atlas labelling dominates c2a's runtime) and not something that
% would be reported. The montage is still shown. Set true in a2 to restore it.
if ~exist('dotables_tfce_unc','var') || isempty(dotables_tfce_unc)
    dotables_tfce_unc = false;
end

% Extent threshold for TFCE. Defaults to 0, i.e. none, and deliberately NOT to
% k_threshold_glm: TFCE already integrates cluster extent into the statistic
% itself - that is what the enhancement does - so a further extent filter counts
% extent twice. And when the map is thresholded on max-statistic FWE p-values,
% familywise error is already controlled across the whole search volume, which is
% the job an extent threshold is usually brought in to approximate. Applying
% k >= 50 on top discards valid FWE-significant voxels: on proj_moodbugs_wp2
% contrast 5 it removed all 42 of them and reported an empty map.
if ~exist('k_threshold_tfce','var') || isempty(k_threshold_tfce)
    k_threshold_tfce = 0;
end



%
% *MVPA*

if dobootstrap_mvpa_reg_cov
    
    mvpa_resultsvarname = 'mvpa_stats_results';
    mvpa_resultsstring = 'mvpa_stats_and_maps_';
    mvpa_analysis_type = algorithm_mvpa_reg_cov;

    if ~exist(mvpa_resultsvarname,'var')

        fprintf('\n\n');
        printhdr('LOADING MVPA DATA');
        fprintf('\n\n');

        savefilenamedata_mvpa = fullfile(resultsdir, ['mvpa_stats_and_maps_', mygroupnamefield, '_', scaling_string, '_', results_suffix, '.mat']);

        if exist(savefilenamedata_mvpa,'file')
            fprintf('\nLoading %s mvpa regression results and maps from %s\n\n', mvpa_analysis_type, savefilenamedata_mvpa);
            load(savefilenamedata_mvpa);
        else
            fprintf('\nNo saved results file %s. Skipping this analysis.', savefilenamedata_mvpa);
            fprintf('\nRun prep_3a_run_second_level_regression_and_save.m to get %s regression results first.\n', mvpa_analysis_type); 
            return
        end

    else
        fprintf('\n%s %s found, displaying results\n\n', mvpa_resultsvarname, mvpa_analysis_type);

    end

end
    

%% VISUALIZE GLM AND MVPA RESULTS FOR EACH CONTRAST
% -------------------------------------------------------------------------

region_objs_fdr = cell(1,size(results,2));
region_tables_fdr = cell(1,size(results,2));
region_tables_cov_fdr = cell(1,size(results,2));

region_objs_unc = cell(1,size(results,2));
region_tables_unc = cell(1,size(results,2));
region_tables_cov_unc = cell(1,size(results,2));

    if has_bayes
        region_objs_Bayes = cell(1,size(bayesian_results,2));
        region_tables_Bayes = cell(1,size(bayesian_results,2));
        region_tables_cov_Bayes = cell(1,size(bayesian_results,2));
    end
    
    if has_tfce
        % region output is produced for the REPORTED correction only (see
        % tfce_correction) - labelling regions against an atlas is the slowest
        % step in this script, and the maps below are saved either way.
        region_objs_tfce_corr = cell(1,size(tfce_results,2));
        region_tables_tfce_corr = cell(1,size(tfce_results,2));
        region_tables_cov_tfce_corr = cell(1,size(tfce_results,2));
        
        % both corrections' thresholded maps, saved regardless of which is reported
        tfce_stat_imgs_thr_fdr = cell(1,size(tfce_results,2));
        tfce_stat_imgs_thr_fwe = cell(1,size(tfce_results,2));

        region_objs_tfce_unc = cell(1,size(tfce_results,2));
        region_tables_tfce_unc = cell(1,size(tfce_results,2)); 
        region_tables_cov_tfce_unc = cell(1,size(tfce_results,2));
    end
        

    
for c = 1:size(results, 2) % number of contrasts or conditions
    
    %%
    % *GLM*

    analysisname = results{c}.analysis_name;
    names = results{c}.variable_names;
    
    names_string = names{1};
    
        for name = 2:size(names,2)
            names_string = [names_string,' ',names{name}];
        end
    
        if ~dorobfit_parcelwise

            t = results{c}.t;               % NOTE: this statistic_object is unthresholded AND unmasked (except for a brainmask)
            
            t = apply_mask(t,brainmask);    % re-apply brainmask just to be sure
            
            if exist('maskname_short','var')
                voxelsize_glmmask = diag(glmmask.volInfo.mat(1:3, 1:3))';
                if ~isequal(voxelsize_glmmask,t)
                    glmmask = resample_space(glmmask,t);
                end
            end
        
            glmmask.dat(glmmask.dat < 1) = 0;   % re-binarize mask, resample_space causes non-zero non-one values at inner cortical boundaries

            if apply_mask_before_fdr
                t = apply_mask(t, glmmask);
            end

        else

            t = results{c}.t_obj;           % NOTE: this statistic_object is thresholded at FDR q < 0.05, resampled to the space of the fmri_data_object and masked by the atlas in the previous script!
            k_threshold_glm = 0;            % we don't want an extent threshold for parcelwise as it could eliminate small parcels

        end

        if has_bayes

            BF = bayesian_results{c}.BF;    % NOTE: unthresholded in both cases, masked in case of parcelwise only

            if ~dorobfit_parcelwise

                if apply_mask_before_fdr
                    
                    for j = 1:size(BF,2)
                        BF(j) = apply_mask(BF(j), glmmask);

                    end
                    
                end

            end

        end
        
        % TFCE may have been restricted to a subset of contrasts via cons2tfce in
        % prep_3a, in which case the cells for the other contrasts are empty.
        % Report TFCE only where it was actually computed - dereferencing an empty
        % cell here would error out the whole script on the first such contrast.
        
        has_tfce_c = has_tfce && numel(tfce_results) >= c && ~isempty(tfce_results{c});
        
        if has_tfce && ~has_tfce_c
            fprintf('\nno TFCE results for contrast %d (%s) - not in cons2tfce; skipping TFCE for it\n\n', ...
                c, analysisname);
        end
        
        if has_tfce_c
            
            tfce_stat_img = tfce_results{c}.tfce_stat_img;  % NOTE: unthresholded and unmasked
            tfce_dat = tfce_results{c}.tfce_dat;
            
            % WHICH TFCE CORRECTION TO REPORT
            % -------------------------------
            % tfce_info.p_FWE holds the max-statistic FWE-corrected p-values.
            % They are already corrected, so they get thresholded 'unc' at
            % p_threshold_fwe further down; running FDR on them would correct
            % twice. The swap of .p happens HERE, before apply_mask, because
            % p_FWE is indexed over the unmasked voxel list - masking first
            % would misalign the two.
            
            if ~exist('tfce_correction','var') || isempty(tfce_correction)
                tfce_correction = 'fwe';
            end
            
            if ~exist('p_threshold_fwe','var') || isempty(p_threshold_fwe)
                p_threshold_fwe = 0.05;
            end
            
            % p_FWE was added to group_tfce_from_subject_maps only recently, so
            % results generated before that carry none. It is fully recoverable
            % from what they DO store - the observed TFCE map and the
            % max-statistic null - so recompute it rather than force a rerun of
            % the permutations, which is by far the most expensive step here.
            
            tfce_p_fwe = [];
            
            if isfield(tfce_results{c},'tfce_info')
                
                if isfield(tfce_results{c}.tfce_info,'p_FWE') && ~isempty(tfce_results{c}.tfce_info.p_FWE)
                    
                    tfce_p_fwe = tfce_results{c}.tfce_info.p_FWE;
                    
                elseif all(isfield(tfce_results{c}.tfce_info,{'TFCE_real','TFCE_null_max'}))
                    
                    n_perm_saved = numel(tfce_results{c}.tfce_info.TFCE_null_max);
                    
                    fprintf(['\nNOTE: no p_FWE stored for contrast %d - these TFCE results predate the FWE\n' ...
                             'implementation. Recomputing it from the saved max-statistic null:\n' ...
                             '%d permutations, so the finest attainable p is %.4f.\n\n'], ...
                             c, n_perm_saved, 1/(n_perm_saved+1));
                    
                    tfce_p_fwe = tfce_fwe_from_null(tfce_results{c}.tfce_info.TFCE_real, ...
                                                    tfce_results{c}.tfce_info.TFCE_null_max);
                    
                end
                
            end
            
            has_p_fwe = ~isempty(tfce_p_fwe);
            
            if ~has_p_fwe && ~strcmpi(tfce_correction,'fdr')
                warning('c2a:noTFCEfwe', ...
                    ['contrast %d carries neither p_FWE nor the max-statistic null needed to\n' ...
                     'recompute it, so FWE is unavailable. Reporting FDR instead.'], c);
                tfce_correction = 'fdr';
            end
            
            tfce_stat_img_fwe = [];
            
            if has_p_fwe
                % swap uncorrected for FWE-corrected p BEFORE masking, so the p
                % vector and the image voxels stay aligned
                tfce_stat_img_fwe = tfce_stat_img;
                tfce_stat_img_fwe.p = tfce_p_fwe;
            end
            
            if apply_mask_before_fdr
                
                tfce_stat_img = apply_mask(tfce_stat_img, glmmask);
                
                if ~isempty(tfce_stat_img_fwe)
                    tfce_stat_img_fwe = apply_mask(tfce_stat_img_fwe, glmmask);
                end
                
                % Lukas' original code
                % causes mismatch in length of .dat fields between 
