                fprintf('\n\n');

                t0_boot = tic;
                
                switch algorithm_mvpa_reg_cov   % TO DO: add optimal alpha and lambda lasso parameters from nested cv in predict() run in prep_3a, should be stored in stats.other_output somewhere
                    
                    case 'cv_lassopcr'

                        [~ , mvpa_bs_stats{j}] = predict(mvpa_fmri_dats{j}, 'algorithm_name', algorithm_mvpa_reg_cov,...
                            'bootsamples', boot_n_mvpa_reg_cov, 'nfolds', 1, 'error_type', 'mse', ...
                            parallelstr_mvpa_reg_cov, 'verbose', 0);
                        
                    case 'cv_lassopcr_matlab'
                        
                        [~ , mvpa_bs_stats{j}] = predict(mvpa_fmri_dats{j}, 'algorithm_name', algorithm_mvpa_reg_cov,...
                            'bootsamples', boot_n_mvpa_reg_cov, 'nfolds', 1, 'error_type', 'mse', ...
                            parallelstr_mvpa_reg_cov, 'verbose', 0);
                        
                    otherwise
                        
                        [~ , mvpa_bs_stats{j}] = predict(mvpa_fmri_dats{j}, 'algorithm_name', algorithm_mvpa_reg_cov,...
                            'bootsamples', boot_n_mvpa_reg_cov, 'nfolds', 1, 'error_type', 'mse', ...
                            parallelstr_mvpa_reg_cov, 'verbose', 0);
                        
                end

                t_end_boot = toc(t0_boot);

            end % for loop over regressors

            mvpa_bs_stats_results{c} = mvpa_bs_stats;

            fprintf('\n\n');
            printhdr('PLOTTING BOOTSTRAPPED MVPA WEIGHT MAPS');
            fprintf('\n\n');

            fprintf ('\nMONTAGE BOOTSTRAPPED %s RESULTS AT FDR q < %1.4f, k = %d, CONTRAST: %s, REGRESSORS: %s, MASK: %s, SCALING: %s\n\n', upper(algorithm_mvpa_reg_cov), q_threshold_mvpa_reg_cov, k_threshold_mvpa_reg_cov, analysisname, names_string, mask_string, scaling_string);

            o2 = canlab_results_fmridisplay([], 'multirow', mvpa_num_effects);

                for j = 1:mvpa_num_effects

                    tj = mvpa_bs_stats{j}.weight_obj;
                    
                        if apply_mask_before_fdr
                            tj = apply_mask(tj, glmmask);
                        end
                        
                    tj = threshold(tj, q_threshold_mvpa_reg_cov, 'fdr', 'k', k_threshold_mvpa_reg_cov); 
                    
                    datsig = tj.dat(logical(tj.sig));
                    datsigneg = datsig(datsig<0);
                    datsigpos = datsig(datsig>0);

                        if isempty(datsigneg) && ~isempty(datsigpos)

                            o2 = addblobs(o2, region(tj), 'wh_montages', (2*j)-1:2*j, 'mincolor',[.9 .4 0], 'maxcolor', [1 1 0]);%, 'cmaprange', [min(datsigpos) max(datsigpos)]);

                        elseif isempty(datsigpos) && ~isempty(datsigneg)

                            o2 = addblobs(o2, region(tj), 'wh_montages', (2*j)-1:2*j, 'mincolor',[.1 .8 .8], 'maxcolor', [.1 .1 .8]);%, 'cmaprange', [min(datsigneg) max(datsigneg)]);

                        else

                            o2 = addblobs(o2, region(tj), 'wh_montages', (2*j)-1:2*j, 'splitcolor',{[.1 .8 .8] [.1 .1 .8] [.9 .4 0] [1 1 0]});%, 'cmaprange', [min(datsigneg) max(datsigneg) min(datsigpos) max(datsigpos)]);

                        end
                    
                    o2 = legend(o2);

                    o2 = title_montage(o2, 2*j, [analysisname ' FDR ' num2str(q_threshold_mvpa_reg_cov) ' ' names{j} ' ' mask_string ' ' scaling_string]);

                end % for loop over regressors

            figtitle = sprintf('%s_%s_%s_%1.4f_FDR_montage_%s_%s_%s', analysisname, results_suffix, algorithm_mvpa_reg_cov, q_threshold_mvpa_reg_cov, names_string, mask_string, scaling_string);
            set(gcf, 'Tag', figtitle); plugin_set_figure_size;
            drawnow, snapnow;

                if save_figures_glm
                    plugin_save_figure;
                end

            clear o2, clear figtitle, clear j, clear tj
        
        end % if loop exist cons2boot
        
    end % if loop bootstrap
   
end % for loop over contrasts/conditions


%% SAVE RESULTS
