fprintf('\n\n');
printhdr('APPENDING REGION OBJECTS TO SAVED RESULTS');
fprintf('\n\n');
    
    if ~dorobfit_parcelwise
        
        cd(resultsdir); % unannex image_names_and_setup.mat file if already datalad saved to prevent write permission problems
        ! git annex unannex regression_stats_and_maps*.mat
        cd(rootdir);
    
        savefilenamedata_region = fullfile(resultsdir, ['regression_stats_and_maps_', mygroupnamefield, '_', scaling_string, '_', results_suffix, '.mat']);
        save(savefilenamedata_region, 'region_objs_unc', 'region_objs_fdr', 'region_tables_unc', 'region_tables_fdr', 'region_tables_cov_unc', 'region_tables_cov_fdr', '-append');
        
        if has_bayes
            save(savefilenamedata_region, 'region_objs_Bayes', 'region_tables_Bayes', 'region_tables_cov_Bayes', '-append');
        end
        
        if has_tfce
            save(savefilenamedata_region, 'region_objs_tfce_unc', 'region_objs_tfce_corr', 'region_tables_tfce_unc', 'region_tables_tfce_corr', ...
                'region_tables_cov_tfce_unc','region_tables_cov_tfce_corr', ...
                'tfce_stat_imgs_thr_fdr', 'tfce_stat_imgs_thr_fwe', 'tfce_correction', '-append'); 
        end
        
    else
        
        cd(resultsdir); % unannex image_names_and_setup.mat file if already datalad saved to prevent write permission problems
        ! git annex unannex parcelwise_stats_and_maps*.mat
        cd(rootdir);
        
        savefilenamedata_region = fullfile(resultsdir, ['parcelwise_stats_and_maps_', mygroupnamefield, '_', scaling_string, '_', results_suffix, '.mat']);
        save(savefilenamedata_region, 'region_objs_unc', 'region_objs_fdr', 'region_tables_unc', 'region_tables_fdr', 'region_tables_cov_unc', 'region_tables_cov_fdr', '-append');
            
        if has_bayes
            save(savefilenamedata_region, 'region_objs_Bayes', 'region_tables_Bayes', 'region_tables_cov_Bayes', '-append');
        end
        
    end 
        
    fprintf('\nAdded region objects for %s\n', mygroupnamefield);

    fprintf('\nFilename: %s\n', savefilenamedata_region);
    

if dobootstrap_mvpa_reg_cov
    
    fprintf('\n\n');
    printhdr('APPENDING BOOTSTRAPPED MVPA RESULTS');
    fprintf('\n\n');
    
    savefilenamedata_mvpa = fullfile(resultsdir, ['mvpa_stats_and_maps_', mygroupnamefield, '_', scaling_string, '_', results_suffix, '.mat']);
    save(savefilenamedata_mvpa, 'mvpa_bs_stats_results','-append');
    fprintf('\nSaved mvpa_stats_results for %s\n', mygroupnamefield);

    fprintf('\nFilename: %s\n', savefilenamedata_mvpa);

end